import type { Post } from '#blog/domain/post'
import type { PostRepository } from '../../application/ports/post-repository'

/** In-memory PostRepository for use-case tests. Same contract as the Drizzle one. */
export const memoryPostRepository = (seed: Post[] = []): PostRepository => {
  const rows = new Map(seed.map(post => [post.id, post]))
  const sorted = () => [...rows.values()].sort((a, b) => b.createdAt.localeCompare(a.createdAt))
  return {
    async list({ limit, offset }) {
      return { items: sorted().slice(offset, offset + limit), total: rows.size }
    },
    async get(id) {
      return rows.get(id)
    },
    async findBySlug(slug) {
      return [...rows.values()].find(post => post.slug === slug)
    },
    async create(post) {
      rows.set(post.id, post)
      return post
    },
    async update(id, post) {
      rows.set(id, post)
      return post
    },
    async delete(id) {
      rows.delete(id)
    }
  }
}
